mapper.select:
SELECT shop_id as shopId, DATE(create_time) as billDate, SUM(divide_amount) as totalDivideAmount, SUM(handling_charge) as totalHandlingCharge, SUM(platform_charge) as totalPlatformCharge, COUNT(id) as totalCount FROM order_divide_log
AND create_time >= #{data.startTime} AND create_time <= #{data.endTime}
GROUP BY shop_id

SELECT COUNT(DISTINCT bill_date) FROM reconciliation_transaction_summary


        AND bill_date IN

            #{id}


     AND shop_id = #{data.shopId} 
     AND bill_date >= DATE(#{data.startTime}) 
     AND bill_date <= DATE(#{data.endTime})

SELECT create_time as transactionTime, COALESCE(divide_amount / 100.0, 0) as divideAmount,
COALESCE(handling_charge / 100.0, 0) as tongGuanFee, COALESCE(platform_charge / 100.0, 0) as platformFee,
COALESCE(amount / 100.0, 0) as orderAmount, order_no as orderNo, divide_no as subLedgerRequestNo
FROM order_divide_log

     AND shop_id = #{data.shopId} 
     AND create_time >= #{data.startTime} 
     AND create_time <= #{data.endTime} 
     AND order_no LIKE CONCAT('%',#{data.orderNo},'%') 
     AND divide_no LIKE CONCAT('%',#{data.subLedgerRequestNo},'%') 

ORDER BY create_time DESC

SELECT COUNT(0) FROM order_divide_log

     AND shop_id = #{data.shopId} 
     AND create_time >= #{data.startTime} 
     AND create_time <= #{data.endTime} 
     AND order_no LIKE CONCAT('%',#{data.orderNo},'%') 
     AND divide_no LIKE CONCAT('%',#{data.subLedgerRequestNo},'%')

SELECT COUNT(0) as totalCount,
IFNULL(SUM(divide_amount / 100.0), 0) as totalDivideAmount,
IFNULL(SUM(handling_charge / 100.0), 0) as totalTongGuanFee,
IFNULL(SUM(platform_charge / 100.0), 0) as totalPlatformFee
FROM order_divide_log

     AND shop_id = #{data.shopId} 
     AND create_time >= #{data.startTime} 
     AND create_time <= #{data.endTime} 
     AND order_no LIKE CONCAT('%',#{data.orderNo},'%') 
     AND divide_no LIKE CONCAT('%',#{data.subLedgerRequestNo},'%')

SELECT
DATE_FORMAT(create_time, '%Y-%m-%d') as settlementTime,
IFNULL(SUM(divide_amount) / 100.0, 0) as settlementAmount,
IFNULL(MAX(platform_rate), 0) as platformRate
FROM order_divide_log

    shop_id = #{data.shopId}
     AND DATE(create_time) >= #{data.startDate} 
     AND DATE(create_time) <= #{data.endDate} 

GROUP BY DATE_FORMAT(create_time, '%Y-%m-%d')
ORDER BY settlementTime DESC

SELECT COUNT(DISTINCT DATE_FORMAT(create_time, '%Y-%m-%d'))
FROM order_divide_log

    shop_id = #{data.shopId}
     AND DATE(create_time) >= #{data.startDate} 
     AND DATE(create_time) <= #{data.endDate}

SELECT
COUNT(0) as totalCount,
IFNULL(SUM(divide_amount / 100.0), 0) as totalAmount
FROM order_divide_log

    shop_id = #{data.shopId}
     AND DATE(create_time) >= #{data.startDate} 
     AND DATE(create_time) <= #{data.endDate}
